
const isTeacher=document.body.dataset.view==='teacher';
const titles=['Двойная бронь','Словарь бронирования','Пересечение интервалов','Бронь №42','Модель бронирования','Одни правила для сайта и бота','Создание брони','Отмена брони','Два одновременных запроса','Бронь и уведомление','Перенос встречи','Модель и проверки','Uber и Shopify','Зависимости кода','DDD'];
let scene=14,modelStep=0,raceStep=0,safe=false,moved=false,pseudoShown=false,time=90;
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const head=(title,lead='')=>'<h1>'+title+'</h1>'+(lead?'<p class="lead">'+lead+'</p>':'');
const prompt=()=>'';
const box=(title,body,kind='')=>'<div class="tile '+kind+'"><h2>'+title+'</h2><div>'+body+'</div></div>';
const row=(items)=>'<div class="flow">'+items.map((x,i)=>box(x[0],x[1])+(i<items.length-1?'<span class="connector">→</span>':'')).join('')+'</div>';
const code=s=>'<pre>'+esc(s)+'</pre>';
const pseudos={2:'a.Start < b.End && b.Start < a.End',4:'schedule.Book(interval, organizerId);',5:'// И сайт, и бот вызывают одно действие\napplication.CreateBooking(roomId, interval);',6:'schedule = repository.Load(roomId, date);\nschedule.Book(interval, currentUser.Id);\nrepository.Save(schedule);',7:'Cancel(userId):\n  если userId != OrganizerId: отказ\n  Status = Canceled',8:'Одна транзакция:\n  UPDATE расписания WHERE Version = 7\n  если обновлено 0 строк: откат\n  INSERT брони; COMMIT',10:'Reschedule(id, interval, userId):\n  проверить автора и статус\n  проверить другие брони\n  изменить время; сохранить'};
function timeline(){const start=540+time,label=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0'),overlap=time<120&&time+60>60;return '<div class="timelineSheet"><div class="ticks"><span>09:00</span><span>10:00</span><span>11:00</span><span>12:00</span><span>13:00</span></div><div class="track"><div class="reservation a" style="left:25%;width:25%">А · 10:00–11:00</div></div><div class="track"><div class="reservation b" style="left:'+(time/240*100)+'%;width:25%">Б · '+label(start)+'–'+label(start+60)+'</div></div><div class="controls"><label for="time">Начало Б</label><input id="time" type="range" min="0" max="180" step="15" value="'+time+'" oninput="setTime(this.value)"><span class="verdict '+(overlap?'bad':'good')+'">'+(overlap?'Пересечение':'Свободно')+'</span></div></div>'}
function setTime(v){time=Number(v);const label=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0'),start=540+time,overlap=time<120&&time+60>60;const bar=document.querySelector('.reservation.b');bar.style.left=(time/240*100)+'%';bar.textContent='Б · '+label(start)+'–'+label(start+60);const verdict=document.querySelector('.verdict');verdict.textContent=overlap?'Пересечение':'Свободно';verdict.className='verdict '+(overlap?'bad':'good');}
function concurrent(){const a=['Читает: свободно · v7','Проверяет время','Записывает · v8'];const b=['Читает: свободно · v7','Проверяет время',safe?'Запись с v7 отклонена':'Записывает вторую бронь', 'Читает v8: занято'];return '<div class="raceGrid">'+box('Запрос А',a.map((x,i)=>'<div class="event '+(raceStep<=i?'pending':'')+'">'+x+'</div>').join(''))+'<div class="result"><span class="bigNumber">'+(raceStep<3?0:safe?1:2)+'</span><span>'+(raceStep>=3&&safe?'бронь':raceStep>=3?'брони':'броней')+'</span></div>'+box('Запрос Б',b.slice(0,safe?4:3).map((x,i)=>'<div class="event '+(raceStep<=i?'pending':'')+' '+(i===2?'bad':'')+'">'+x+'</div>').join(''))+'</div><div class="controls"><button onclick="raceStep=Math.min('+(safe?4:3)+',raceStep+1);render()">Следующий шаг</button><button onclick="safe=!safe;raceStep=0;render()">'+(safe?'Без защиты':'С проверкой версии')+'</button><button onclick="raceStep=0;render()">Сбросить</button></div>'}
function slide(){switch(scene){
case 14:return head('DDD','Предметно-ориентированное проектирование')+row([['Работа людей','Одна комната — одна встреча'],['Правило','Брони не пересекаются'],['Модель','Расписание проверяет время']]);
case 12:return head('Uber / Shopify')+'<div class="companies">'+box('Uber · 2020','<div class="tags"><span>Карты</span><span>Тарифы</span><span>Подбор водителя</span></div><p>Сервисы сгруппированы по задачам бизнеса.</p><div class="outcome">Другие команды используют одну точку входа</div>','uber')+box('Shopify · 2019 / 2024','<div class="tags"><span>Заказы</span><span>Доставка</span><span>Товары</span></div><p>Модули внутри одного приложения.</p><div class="outcome">Часть системы можно менять отдельно</div>','shopify')+'</div>';
case 0:return head('Одна комната. Две брони.')+'<div class="roomScene"><div class="roomPlan"><span>Север</span><div class="meetingTable"></div><i></i><i></i><i></i><i></i></div><div class="bookingPair">'+box('Команда А','<div class="timeBig">10:00–11:00</div>','blue')+box('Команда Б','<div class="timeBig">10:30–11:30</div>','pink')+'</div></div>';
case 1:return head('Комната ≠ бронь')+'<div class="four">'+box('Комната','Север · 6 мест')+box('Бронь','№42 · команда А')+box('Интервал','10:00–11:00')+box('Организатор','Андрей')+'</div><div class="relationship">Комната ← бронь → интервал</div>';
case 2:return head('Пересечение интервалов')+timeline();
case 3:return head('Бронь №42')+'<div class="identity">'+box('До переноса','<div class="timeBig">10:00–11:00</div><span class="idTag">№42</span>')+'<span class="connector">→</span>'+box('После переноса','<div class="timeBig">12:00–13:00</div><span class="idTag">№42</span>')+'</div><div class="compare">Сущность: тот же номер<br>Интервал: новое значение</div>';
case 4:return head('Модель бронирования')+model()+'<div class="controls"><button onclick="modelStep=Math.min(4,modelStep+1);render()">Следующий объект</button><button onclick="modelStep=0;render()">Скрыть</button></div>';
case 5:return head('Сайт и бот — одни правила')+'<div class="sharedRule"><div class="entry">'+box('Сайт','Создать бронь')+box('Бот','Создать бронь')+'</div><div class="mergeArrow">→</div>'+box('Расписание','Проверяет занятость<br>Создаёт бронь','lime')+'</div>';
case 6:return head('Создание брони')+row([['UI','Принимает комнату и время'],['Application','Загружает расписание'],['Domain','Проверяет и создаёт бронь'],['Infrastructure','Сохраняет результат']]);
case 13:return dependenciesHtml();
case 7:return head('Отмена брони')+'<div class="cancelFlow">'+box('Активна','Занимает время','blue')+'<div class="connector">Cancel →</div>'+box('Отменена','Время свободно','lime')+'</div><div class="actorRule">'+box('Организатор','Разрешено','lime')+box('Другой человек','Отказ','pink')+'</div>';
case 8:return head(safe?'Сохранение с проверкой версии':'Два запроса одновременно')+concurrent();
case 10:return head('Перенос встречи')+'<div class="reschedule"><div class="tile"><span class="idTag">№42</span><div class="timeBig">'+(moved?'12:00–13:00':'10:00–11:00')+'</div><button onclick="moved=!moved;render()">'+(moved?'Исходное время':'На 12:00')+'</button></div><div class="checkList"><span>Своя бронь</span><span>Активный статус</span><span>Корректное время</span><span>Нет пересечений</span></div></div>';
case 11:return head('Модель и проверки')+'<div class="responsibilities">'+[['TimeInterval','Начало раньше конца','Пересечение'],['Booking','Организатор и статус','Отмена'],['RoomSchedule','Другие брони комнаты','Бронирование / перенос']].map(([a,b,c])=>'<div class="responsibility"><h2>'+a+'</h2><span>'+b+'</span><strong>'+c+'</strong></div>').join('')+'</div>';
case 9:return head('Бронь есть. Сообщения нет.')+row([['База','Бронь сохранена'],['Telegram','Сообщение не доставлено'],['Повторная попытка','Отправить позже']]);
}}
function teacherHtml(){const g=teacherGuides[scene],i=lessonOrder.indexOf(scene),start=lessonMinutes.slice(0,i).reduce((a,b)=>a+b,0);return '<div class="teacherTitle"><h1>'+titles[scene]+'</h1><span>'+ (lessonMinutes[i]?start+'–'+(start+lessonMinutes[i])+' мин':'Бонус')+'</span></div><section><h2>Скажи</h2><p class="say">'+esc(g.say)+'</p></section><section><h2>Объяснение для тебя</h2>'+g.explain.map(x=>'<p>'+esc(x)+'</p>').join('')+'</section><section><h2>Что сделать</h2><ol>'+g.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></section><section><h2>Спроси группу</h2>'+g.qa.map(x=>'<div class="qa"><h3>'+esc(x.q)+'</h3><p>'+esc(x.a)+'</p></div>').join('')+'</section><details><summary>Если спросят подробнее</summary><p>'+esc(g.extra)+'</p></details>'+(pseudos[scene]?'<details><summary>Псевдокод и его смысл</summary>'+code(pseudos[scene])+'<p>'+esc(g.codeHelp||'Это запись идеи. Полного приложения на паре не пишем.')+'</p></details>':'')+'<details><summary>Источники и сверка с лекциями</summary><p>'+esc(g.lecture)+'</p>'+g.sources.map(([a,b])=>'<a target="_blank" rel="noopener" href="'+b+'">'+esc(a)+'</a>').join('')+'</details>'+ (scene===14?'<details><summary>Как вести пару · план на 60 минут</summary><p>Открой показ во втором окне. Окна листаются независимо. На проекторе схемы; здесь реплики и ответы. Обсуждайте правила вместе со студентами. Писать приложение не требуется.</p><ol>'+lessonOrder.map((id,i)=>'<li>'+titles[id]+' · '+(lessonMinutes[i]?lessonMinutes[i]+' мин':'бонус')+'</li>').join('')+'</ol><p>Время включает ответы группы. Если задержались, пропусти бонус про уведомления.</p></details>':'')}
function render(){document.getElementById('stage').innerHTML=slide()+(pseudoShown&&pseudos[scene]?code(pseudos[scene]):'');document.getElementById('teacher').innerHTML=isTeacher?teacherHtml():'';const index=lessonOrder.indexOf(scene);document.getElementById('dots').innerHTML=lessonOrder.map((id,i)=>'<button class="dot '+(id===scene?'current':'')+'" aria-label="'+(i+1)+'. '+titles[id]+'" '+(id===scene?'aria-current="step"':'')+' onclick="go('+i+')">'+(i+1)+'</button>').join('');document.getElementById('position').textContent=(index+1)+' / '+lessonOrder.length+' · '+titles[scene];document.getElementById('prev').disabled=index===0;document.getElementById('next').disabled=index===lessonOrder.length-1;document.getElementById('progress').style.width=((index+1)/lessonOrder.length*100)+'%';document.getElementById('pseudoButton').hidden=isTeacher||!pseudos[scene];requestAnimationFrame(fitStage);}
function go(i){scene=lessonOrder[Math.max(0,Math.min(lessonOrder.length-1,i))];pseudoShown=false;render();history.replaceState(null,'','#scene='+scene);document.getElementById('teacher').scrollTop=0;window.scrollTo(0,0);}
function fitStage(){if(isTeacher)return;const el=document.getElementById('stage');el.style.transform='none';const top=document.querySelector('header').getBoundingClientRect().bottom+22,height=document.querySelector('.bottom').getBoundingClientRect().top-top-20;const scale=Math.min((innerWidth-48)/1440,height/el.offsetHeight,1.5);el.style.top=top+'px';el.style.transform='scale('+scale+')';el.style.marginLeft=(-720*scale)+'px';}
document.getElementById('prev').onclick=()=>go(lessonOrder.indexOf(scene)-1);document.getElementById('next').onclick=()=>go(lessonOrder.indexOf(scene)+1);document.getElementById('resetLesson').onclick=()=>go(0);document.getElementById('pseudoButton').onclick=()=>{pseudoShown=!pseudoShown;render()};document.getElementById('fullButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};if(isTeacher)document.getElementById('openProjector').onclick=()=>window.open('index.html','ddd-projector');
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(lessonOrder.indexOf(scene)+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(lessonOrder.indexOf(scene)-1)}});addEventListener('resize',fitStage);document.addEventListener('fullscreenchange',fitStage);const requested=Number(location.hash.match(/scene=(\d+)/)?.[1]);if(lessonOrder.includes(requested))scene=requested;render();
